from marshmallow import Schema, fields

class ArticleSchema(Schema):
    id = fields.Int()
    title = fields.Str()
    can_edit = fields.Method("get_can_edit")

    def get_can_edit(self, obj):
        user = self.context.get("user")
        return user is not None and user["id"] == obj["author_id"]

def serialize_article(article: dict, user: dict | None) -> dict:
    try:
        return ArticleSchema(context={"user": user}).dump(article)
    except TypeError as e:
        print(f"Caught expected error: {e}")
        return None

article = {"id": 1, "title": "Hello", "author_id": 10}
user = {"id": 10}
result = serialize_article(article, user)
if result is None:
    print("Reproduction successful: TypeError raised")
else:
    print(f"Reproduction failed: result is {result}")
