from articles.service import serialize_article

def test_serialize_article_author():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = {"id": 10}
    result = serialize_article(article, user)
    assert result["can_edit"] is True

def test_serialize_article_other_user():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = {"id": 11}
    result = serialize_article(article, user)
    assert result["can_edit"] is False

def test_serialize_article_no_user():
    article = {"id": 1, "title": "Hello", "author_id": 10}
    user = None
    result = serialize_article(article, user)
    assert result["can_edit"] is False

